from sklearn.decomposition import PCA
from sklearn.metrics import silhouette_score
from sklearn.preprocessing import StandardScaler

# ------------------------------------------------------------
# 앱 기본 설정 및 데이터
# 첨부된 공식 CSV를 압축해 main.py 안에 포함했으므로 별도 업로드가 필요 없습니다.
# ------------------------------------------------------------
APP_TITLE = "공공도서관 유형 분석"
DATA_SOURCE_URL = "https://www.data.go.kr/data/15072611/fileData.do?recommendDataYn=Y"
DATA_GZIP_BASE64 = ""

st.set_page_config(page_title=APP_TITLE, page_icon="📚", layout="wide")

CORE_FEATURES = ["장서수(인쇄)", "사서수", "대출자수", "대출권수"]
EXTRA_FEATURES = ["자료구입비(천원)"]
NUMERIC_COLUMNS = CORE_FEATURES + EXTRA_FEATURES
DISPLAY_COLUMNS = ["도서관명", "행정구역", "시군구"]

@st.cache_data(show_spinner="공공도서관 데이터를 불러오는 중입니다...")
def load_data():
    """main.py에 포함된 CP949 CSV를 읽습니다."""
    csv_bytes = gzip.decompress(base64.b64decode(DATA_GZIP_BASE64))
    df = pd.read_csv(BytesIO(csv_bytes), encoding="cp949", dtype={"도서관코드": str})
    for col in NUMERIC_COLUMNS + ["평가년도"]:
        if col in df.columns:
            df[col] = pd.to_numeric(df[col], errors="coerce")
    return df


def safe_silhouette(x, labels, ignore_noise=False):
    labels = np.asarray(labels)
    mask = labels != -1 if ignore_noise else np.ones(len(labels), dtype=bool)
    x_use = x[mask]
    y_use = labels[mask]
    unique = np.unique(y_use)
    if len(unique) < 2 or len(unique) >= len(y_use):
        return np.nan
    try:
        return float(silhouette_score(x_use, y_use))
    except Exception:
        return np.nan


def display_cluster_label(value):
    value = int(value)
    return "노이즈" if value == -1 else f"군집 {value + 1}"


def prepare_data(df, features, exclude_no_borrow, use_log):
    work = df.copy()
    initial_rows = len(work)
    both_zero_count = int(((work["대출자수"] == 0) & (work["대출권수"] == 0)).sum())
    if exclude_no_borrow:
        work = work.loc[~((work["대출자수"] == 0) & (work["대출권수"] == 0))].copy()

    for col in features:
        work[col] = pd.to_numeric(work[col], errors="coerce")

    # 선택 변수에 결측치가 있거나 음수가 있는 행만 제외합니다.
    valid = work[features].notna().all(axis=1)
    valid &= (work[features] >= 0).all(axis=1)
    removed_invalid = int((~valid).sum())
    work = work.loc[valid].copy()

    raw_x = work[features].astype(float).copy()
    transformed = np.log1p(raw_x) if use_log else raw_x.copy()
    scaler = StandardScaler()
    scaled_x = scaler.fit_transform(transformed)
    return work, raw_x, transformed, scaled_x, {
        "initial_rows": initial_rows,
        "both_zero_count": both_zero_count,
        "removed_invalid": removed_invalid,
        "final_rows": len(work),
    }


def run_models(work, raw_x, scaled_x, k, eps, min_samples):
    km = KMeans(n_clusters=k, random_state=42, n_init=20)
    km_labels = km.fit_predict(scaled_x)

    hierarchical = AgglomerativeClustering(n_clusters=k, linkage="ward")
    hierarchical_labels = hierarchical.fit_predict(scaled_x)

    dbscan = DBSCAN(eps=eps, min_samples=min_samples)
    dbscan_labels = dbscan.fit_predict(scaled_x)

    model_results = {
        "K-평균 군집": km_labels,
        "계층적 군집": hierarchical_labels,
        "DBSCAN": dbscan_labels,
    }
    rows = []
    for name, labels in model_results.items():
        labels = np.asarray(labels)
        cluster_count = len(set(labels) - {-1})
        noise_count = int((labels == -1).sum())
        score = safe_silhouette(scaled_x, labels, ignore_noise=(name == "DBSCAN"))
        rows.append({
            "모델": name,
            "군집 수": cluster_count,
            "노이즈 수": noise_count,
            "실루엣 점수": score,
        })

    result_df = work[DISPLAY_COLUMNS + ["도서관코드"] + NUMERIC_COLUMNS].copy()
    for name, labels in model_results.items():
        result_df[name] = [display_cluster_label(v) for v in labels]

    pca = PCA(n_components=2, random_state=42)
    pca_xy = pca.fit_transform(scaled_x)
    pca_df = work[DISPLAY_COLUMNS].copy()
    pca_df["주성분 1"] = pca_xy[:, 0]
    pca_df["주성분 2"] = pca_xy[:, 1]
    for name, labels in model_results.items():
        pca_df[name] = [display_cluster_label(v) for v in labels]

    return model_results, pd.DataFrame(rows), result_df, pca_df


def make_cluster_summary(work, raw_x, labels, features):
    temp = raw_x.copy()
    temp["군집"] = [display_cluster_label(v) for v in labels]
    summary = temp.groupby("군집", sort=False)[features].agg(["count", "mean", "median"])
    summary.columns = [f"{feature}_{stat}" for feature, stat in summary.columns]
    summary = summary.reset_index()
    return summary


